def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    h, w = H // 2, W // 2
    quads = [g[:h, :w], g[:h, w:], g[h:, :w], g[h:, w:]]
    layers = {}
    for q in quads:
        cols = [c for c in np.unique(q) if c != 0]
        if cols:
            layers[int(cols[0])] = q
    priority = [3, 9, 8, 4]  # top to bottom, same in every train pair
    out = np.zeros((h, w), dtype=int)
    emit(out, "Allocate an empty canvas the size of one quadrant.")
    for c in reversed(priority):
        if c in layers:
            q = layers[c]
            out = np.where(q != 0, q, out)
            emit(out, f"Overlay the colour-{c} quadrant; its cells cover lower-priority layers.")
    # any extra colours not in the priority list go underneath (none expected)
    return out
